diff --git a/api.mjs b/api.mjs
index 0e9ddde..2017b6a 100644
--- a/api.mjs
+++ b/api.mjs
@@ -1,3 +1,17 @@
 export function splitName(full) {
-  return full.split(' ');
+  const parts = full.split(' ');
+  
+  if (parts.length === 0) {
+    return ['', ''];
+  }
+  
+  if (parts.length === 1) {
+    return [parts[0], ''];
+  }
+  
+  // For multiple parts, assume last is surname and rest are given names
+  const lastName = parts[parts.length - 1];
+  const firstName = parts.slice(0, -1).join(' ');
+  
+  return [lastName, firstName];
 }

diff --git a/api.mjs b/api.mjs
index 0e9ddde..7947ae2 100644
--- a/api.mjs
+++ b/api.mjs
@@ -1,3 +1,16 @@
 export function splitName(full) {
-  return full.split(' ');
+  const parts = full.split(' ');
+  
+  // Ensure we always return a 2-element array [last, first]
+  if (parts.length === 0) {
+    return ['', ''];
+  } else if (parts.length === 1) {
+    // Single word: treat as last name, first is empty
+    return [parts[0], ''];
+  } else {
+    // Multiple words: last word is last name, others are first names
+    const lastName = parts[parts.length - 1];
+    const firstName = parts.slice(0, parts.length - 1).join(' ');
+    return [lastName, firstName];
+  }
 }

