index 3940b61..db71cf7 100644
--- a/api.mjs
+++ b/api.mjs
@@ -1,3 +1,15 @@
 export function parsePrice(text) {
-  return Number(text);
+  // Remove leading '$' if present
+  const cleanText = text.startsWith('$') ? text.substring(1) : text;
+  
+  // Handle the case where we might have trailing whitespace or other issues
+  const trimmedText = cleanText.trim();
+  
+  // Parse as float and convert to cents
+  const dollars = parseFloat(trimmedText);
+  
+  // Ensure we're getting the right value by checking our math
+  const cents = Math.round(dollars * 100);
+  
+  return cents;
 }

